"use client";

import * as React from "react";

import { GeoTraceroute, type TraceHop } from "@/components/lumesec/geo-traceroute";

const hops: TraceHop[] = [
  { address: "192.168.1.1", name: "router.home.arpa", rtt: [0.6, 0.5, 0.7] },
  { address: "203.0.113.14", location: "Frankfurt", lat: 50.11, lon: 8.68, rtt: [8.4, 8.1, 9.0] },
  { address: "*", rtt: [] },
  { address: "192.0.2.33", location: "Mumbai", lat: 19.08, lon: 72.88, rtt: [110.4, 109.8, 111.2] },
  { address: "203.0.113.200", name: "app.example.com", location: "Singapore", lat: 1.35, lon: 103.82, rtt: [162.4, 161.9, 163.0] },
];

export function Example() {
  const [hop, setHop] = React.useState<number | null>(null);
  return <GeoTraceroute target="app.example.com" hops={hops} value={hop} onValueChange={setHop} />;
}
